mapper.select:
SELECT MAX(version)
FROM chapter_versions
WHERE chapter_id = #{chapterId}

mapper.delete:
DELETE FROM chapter_versions
WHERE chapter_id = #{chapterId}
AND version NOT IN (
    SELECT version FROM (
        SELECT version FROM chapter_versions
        WHERE chapter_id = #{chapterId}
        ORDER BY version DESC
        LIMIT #{keepCount}
    ) AS t
)
